  txt('Verify sketch', { style: 'Label/Default', color: 'color/text/on-ink', parent: c, name: 'Label' });
  txt('⌘R', { style: 'Label/Small', color: 'color/text/on-ink', parent: c, name: 'Shortcut', opacity: 0.7 });
