function docSection(parent, title, desc) {
  const s = box({ name: 'Section — ' + title, dir: 'V', gap: 20, pad: 40, parent, wSize: 'fill', fill: 'color/bg/panel', radius: 12, stroke: 'color/border/default' });
  const h = box({ name: 'Doc header', dir: 'V', gap: 6, parent: s });
  txt(title, { style: 'Heading/H1', parent: h, name: 'Title' });
  if (desc) txt(desc, { style: 'Body/Default', color: 'color/text/secondary', parent: h, name: 'Description', w: 1000 });
  return s;
}
function swatchBig(parent, varName, name, hex, use, dark) {
  const c = box({ name: 'Swatch ' + name, dir: 'V', gap: 8, w: 200, parent });
  const t = box({ name: 'Tile', dir: 'V', h: 120, pad: 12, align: 'end', radius: 8, fill: varName, stroke: 'color/border/default', parent: c, wSize: 'fill' });
  txt(hex, { style: 'Code/Small', color: dark ? 'color/text/on-ink' : 'color/text/primary', parent: t, name: 'Hex' });
  txt(name, { style: 'Label/Strong', parent: c, name: 'Name' });
  txt(use, { style: 'Caption/Default', color: 'color/text/tertiary', parent: c, name: 'Use', fill: true });
  return c;
}

function buildFoundations(page) {
  const root = box({ name: 'Foundations', dir: 'V', gap: 32, pad: 64, w: 1600, fill: 'color/bg/app', parent: page });
  root.x = 0; root.y = 0;

  // ---- cover: the box front
  const cover = box({ name: 'Cover', dir: 'H', pad: [48, 56, 48, 56], h: 420, cross: 'center', radius: 16, fill: 'color/bg/brand', clip: true, parent: root, wSize: 'fill' });
  contours(cover, 1472, 420, 'color/decor/contour');
  const cl = box({ name: 'Cover text', dir: 'V', gap: 16, parent: cover, grow: true });
  const lock = CMP['Logo/Product Lockup'].createInstance(); cl.appendChild(lock); lock.rescale(1.8);
  txt('Design system', { style: 'Heading/Display', parent: cl, name: 'Title' });
  txt('Taken from the RoboCore V2 box: navy ink, RoboCore yellow and cream paper. One ink, one highlight, nothing else.', { style: 'Body/Default', parent: cl, name: 'Intro', w: 560 });
  txt('Build. Code. Create.', { style: 'Heading/H2', parent: cl, name: 'Tagline' });
  const art = artRect(cover, 'robot', 460, 'Robot line art');
  art.layoutPositioning = 'ABSOLUTE'; art.x = 1472 - 520; art.y = 10;

  // ---- colour
  const col = docSection(root, 'Colour', 'Monochrome: every surface, text and icon is navy ink or a navy tint on paper. Yellow marks the brand and what is active. States change fill, outline or icon — never hue.');
  const row = box({ name: 'Base colours', dir: 'H', gap: 20, parent: col });
  swatchBig(row, 'color/ink/default', 'Navy ink', '#1B2A41', 'Text, icons, outlines, primary buttons, action blocks', true);
  swatchBig(row, 'color/brand/default', 'RoboCore yellow', '#F2B01E', 'Top bar, active indicator, progress, control blocks — never text');
  swatchBig(row, 'color/bg/app', 'Cream', '#F7F1E3', 'App background (the box’s cream card)');
  swatchBig(row, 'color/bg/panel', 'Paper', '#FFFCF5', 'Panels, cards, editor, canvas');
  swatchBig(row, 'color/text/brand', 'Ochre', '#8A5A00', 'Numbers and strings in code, warnings', true);
  const tints = box({ name: 'Navy tints', dir: 'H', gap: 0, radius: 8, clip: true, stroke: 'color/border/default', parent: col });
  for (const [k, use] of [['navy/100', 'Text'], ['navy/88', 'Hover'], ['navy/72', 'Secondary'], ['navy/66', 'Meta'], ['navy/40', 'Disabled'], ['navy/16', 'Border'], ['navy/10', 'Divider'], ['navy/6', 'Hover fill']]) {
    const t = box({ name: 'Tint ' + k, dir: 'V', gap: 2, pad: 12, w: 140, h: 88, align: 'end', fill: '#' + PRIMITIVES[k].slice(1, 7), parent: tints });
    const dark = ['navy/100', 'navy/88', 'navy/72', 'navy/66'].indexOf(k) >= 0;
    txt(use, { style: 'Label/Strong', color: dark ? 'color/text/on-ink' : 'color/text/primary', parent: t, name: 'Use' });
    txt(k.replace('navy/', '') + '%', { style: 'Code/Small', color: dark ? 'color/text/on-ink' : 'color/text/primary', parent: t, name: 'Value' });
  }
  txt('Contrast on paper: text 13.6:1 · secondary 5.8:1 · meta 4.7:1 · ochre 5.8:1 · navy on yellow 7.6:1', { style: 'Caption/Default', color: 'color/text/tertiary', parent: col, name: 'Contrast' });

  // ---- type
  const ty = docSection(root, 'Type', 'Barlow Condensed for headings (as on the box), Barlow for the interface, ' + FONT_MONO + ' for code.');
  for (const [name, sample] of [['Heading/Display', 'Robocore V2'], ['Heading/H1', 'Board setup'], ['Heading/H2', 'Recent projects'], ['Heading/H3', 'Blink LED'], ['Body/Default', 'Plug RoboCore V2 in with a USB-C data cable.'], ['Label/Strong', 'Upload'], ['Caption/Overline', 'Classroom robot'], ['Code/Default', 'digitalWrite(LED_BUILTIN, HIGH);']]) {
    const r = box({ name: 'Type ' + name, dir: 'H', gap: 24, pad: [10, 0, 10, 0], cross: 'center', parent: ty, wSize: 'fill', stroke: 'color/border/subtle', sides: { b: 1 } });
    const meta = box({ name: 'Meta', dir: 'V', gap: 2, w: 260, parent: r });
    txt(name, { style: 'Label/Strong', parent: meta, name: 'Style' });
    txt(TS[name].font.family + ' ' + TS[name].font.style + ' ' + TS[name].size + '/' + TS[name].lh, { style: 'Caption/Default', color: 'color/text/tertiary', parent: meta, name: 'Spec' });
    txt(sample, { style: name, parent: r, name: 'Sample', grow: true });
  }

  // ---- blocks
  const bl = docSection(root, 'Blocks', 'Three roles instead of eight colours, drawn as line art like the box. Shape still tells you how a block fits: hats start a script, statements stack, values plug in.');
  const br = box({ name: 'Roles', dir: 'H', gap: 24, parent: bl, wSize: 'fill' });
  for (const [role, title, desc, key] of [['control', 'Control', 'Yellow. Start, loops, waits, if.', 'Control/Wait'], ['action', 'Action', 'Navy. LEDs, motors, servos, serial, variables.', 'Output/Set built-in LED'], ['value', 'Value', 'White, outlined. Sensors, inputs, maths.', 'Sensors/Ultrasonic distance']]) {
    const c = box({ name: 'Role ' + title, dir: 'V', gap: 12, pad: 20, radius: 10, fill: 'color/bg/canvas', stroke: 'color/border/default', parent: br, grow: true });
    blk(key, null, c);
    txt(title, { style: 'Heading/H3', parent: c, name: 'Title' });
    txt(desc, { style: 'Body/Small', color: 'color/text/secondary', parent: c, name: 'Desc', fill: true });
  }
  const prog = buildBlinkProgram({ selected: true });
  const pc = box({ name: 'Sample program', dir: 'H', gap: 40, pad: 24, radius: 10, fill: 'color/bg/canvas', stroke: 'color/border/default', parent: bl, wSize: 'fill', cross: 'start' });
  pc.appendChild(prog);
  const pn = box({ name: 'Notes', dir: 'V', gap: 8, parent: pc, grow: true });
  for (const l of ['on start → setup(), forever → loop().', 'Category = toolbox icon + label; role = fill.', 'Yellow outline = selected / keyboard focus.']) txt(l, { style: 'Body/Small', color: 'color/text/secondary', parent: pn, name: 'Note' });

  // ---- states
  const st = docSection(root, 'States', 'Default, hover, focus, disabled. Focus is a navy border with a yellow halo.');
  for (const variant of ['Primary', 'Secondary', 'Ghost']) {
    const r = box({ name: 'States ' + variant, dir: 'H', gap: 24, cross: 'center', parent: st });
    txt(variant, { style: 'Label/Strong', color: 'color/text/secondary', parent: r, name: 'Variant', w: 100 });
    for (const state of ['Default', 'Hover', 'Focus', 'Disabled']) {
      const b = inst('Button', { Variant: variant, State: state }, r, { name: 'Button' }); setProp(b, 'Label', state); setProp(b, 'Show icon', false);
    }
  }

  // ---- rules
  const ru = docSection(root, 'Rules', null);
  const rr = box({ name: 'Rule columns', dir: 'H', gap: 24, parent: ru, wSize: 'fill', cross: 'start' });
  for (const [title, items] of [['Keep it simple', ['One primary button per view.', 'The workspace is the largest area; chrome stays thin.', 'Show only what helps the next step.']], ['Honest hardware', ['“Connected” only when a real port is open.', 'Progress is real toolchain progress.', 'Errors quote the toolchain and say what to do.']], ['Accessible', ['Text ≥ 4.5:1, never yellow text on paper.', 'Status = icon or shape + words, not colour.', 'Every icon button has a tooltip and a label.']]]) {
    const c = box({ name: 'Rules ' + title, dir: 'V', gap: 8, pad: 20, radius: 10, stroke: 'color/border/default', parent: rr, grow: true });
    txt(title, { style: 'Heading/H3', parent: c, name: 'Title' });
    for (const it of items) txt('— ' + it, { style: 'Body/Small', color: 'color/text/secondary', parent: c, name: 'Rule', fill: true });
  }
  return root;
}
// ============================================================================
// 02 — Components page layout + 05 — Prototype wiring
// ============================================================================

function family(root, title, desc, o = {}) {
  const f = box({ name: 'Family — ' + title, dir: 'V', gap: 20, pad: 32, parent: root, wSize: 'fill', fill: 'color/bg/panel', radius: 12, stroke: 'color/border/default' });
  const h = box({ name: 'Doc header', dir: 'V', gap: 4, parent: f });
  txt(title, { style: 'Heading/H1', parent: h, name: 'Title' });
  if (desc) txt(desc, { style: 'Body/Small', color: 'color/text/secondary', parent: h, name: 'Description', w: 1000 });
  return box({ name: 'Content', dir: 'H', wrap: true, gap: o.gap || 32, rowGap: o.gap || 32, parent: f, wSize: 'fill', cross: 'start' });
}
async function yieldUI() { await new Promise(r => setTimeout(r, 0)); }

async function buildComponentsPage(page) {
  const root = box({ name: 'Component library', dir: 'V', gap: 24, pad: 64, w: 2200, fill: 'color/bg/app', parent: page });
  root.x = 0; root.y = 0;
  txt('Components', { style: 'Heading/Display', parent: root, name: 'Title' });
  const t0 = Date.now();
  const brand = family(root, 'Logo & icons', 'Single-ink logo from the box; Lucide line icons at 20px.');
  buildLogos(brand); buildIcons(brand);
  await yieldUI();
  const act = family(root, 'Actions', 'Button, icon button and the build controls.');
  buildButton(act); buildIconButton(act); buildToolbarActions(act);
  const nav = family(root, 'Navigation', 'Sidebar items, mode switch and tabs.');
  buildNavItem(nav); buildModeSwitch(nav); buildFileTab(nav); buildPanelTab(nav);
  const hw = family(root, 'Hardware', 'Board selector, connection status, board card and menu.');
  buildBadge(hw); buildConnection(hw); buildBoardSelector(hw);
  const forms = family(root, 'Forms & feedback', 'Inputs, selects, menus, toggles, tooltip, toasts.');
  buildInputs(forms); buildMenu(forms); buildControls(forms); buildTooltip(forms); buildAvatar(forms); buildToast(forms);
  await yieldUI();
  const blocks = family(root, 'Blocks', 'Toolbox categories and the block library: control (yellow), action (navy), value (outlined). Each block lists the C++ it generates.', { gap: 28 });
  buildCategoryItem(blocks);
  const chrome = family(root, 'App chrome', 'Top bar (box yellow), sidebar and status bar.');
  buildProjectPill(chrome); buildSidebar(chrome); buildTopBar(chrome); buildStatusBar(chrome);
  buildBoardInfo(hw); buildBoardMenu(hw);
  const cards = family(root, 'Cards & dialogs', 'Project and example cards, template tile, dialogs.');
  buildProjectCard(cards); buildExampleCard(cards); buildTiles(cards); buildDialogs(cards);
  await yieldUI();
  buildBlockLibrary(blocks);
  REPORT.timings.components = Date.now() - t0;
  return root;
}

// ---------------------------------------------------------------- prototype
const EASE = { type: 'EASE_OUT' };
function reaction(dest, o = {}) {
  return { trigger: { type: 'ON_CLICK' }, actions: [{ type: 'NODE', destinationId: dest.id, navigation: 'NAVIGATE', transition: { type: o.t || 'SMART_ANIMATE', easing: EASE, duration: o.d || 0.25 }, resetScrollPosition: true }] };
}
async function hotspot(frame, x, y, w, h, dest, name, o) {
  const hs = figma.createFrame();
  hs.name = 'Hotspot · ' + name;
  hs.fills = [];
  frame.appendChild(hs);
  if (isAL(frame)) hs.layoutPositioning = 'ABSOLUTE';
  hs.resize(Math.max(1, w), Math.max(1, h)); hs.x = x; hs.y = y;
  await hs.setReactionsAsync([reaction(dest, o)]);
  REPORT.counts.reactions = (REPORT.counts.reactions || 0) + 1;
  return hs;
}
async function go(frame, nodeName, dest, o = {}) {
  if (!frame || !dest) return;
  const scope = o.within || frame;
  const n = scope.findOne(x => x.name === nodeName && x.visible !== false);
  if (!n) { warn('proto: no "' + nodeName + '" in ' + frame.name); return; }
  try {
    await n.setReactionsAsync([reaction(dest, o)]);
    REPORT.counts.reactions = (REPORT.counts.reactions || 0) + 1;
  } catch (e) {
    const p = relPos(n, frame);
    await hotspot(frame, p.x, p.y, p.w, p.h, dest, nodeName, o);
  }
}
async function buildPrototype(page, IDE, SCR) {
  const P = {};
  const pick = [
    ['home', SCR.home, 'Home'], ['homeNew', SCR.homeNew, 'Home — New project'], ['projects', SCR.projects, 'Projects'], ['examples', SCR.examples, 'Examples'],
    ['libraries', SCR.libraries, 'Libraries'], ['boardSetup', SCR.boardSetup, 'Board Setup'], ['serial', SCR.serial, 'Serial Monitor'], ['settings', SCR.settings, 'Settings'],
    ['blocks', IDE.blocks, 'IDE — Blocks'], ['blocksCollapsed', IDE.blocksCollapsed, 'IDE — Blocks · Console collapsed'], ['code', IDE.code, 'IDE — Code'], ['codeCollapsed', IDE.codeCollapsed, 'IDE — Code · Console collapsed'],
    ['boardMenu', IDE.boardMenu, 'IDE — Board selector'], ['settingsDlg', IDE.settings, 'IDE — Project settings'],
  ];
  let i = 0;
  for (const [k, src, name] of pick) {
    if (!src) { warn('proto source missing ' + k); continue; }
    const c = src.clone();
    page.appendChild(c);
    c.name = 'P · ' + name;
    c.x = (i % 4) * 1600; c.y = Math.floor(i / 4) * 1200;
    P[k] = c; i++;
  }
  const navMap = [['Nav/Home', 'home'], ['Nav/Projects', 'projects'], ['Nav/Libraries', 'libraries'], ['Nav/Examples', 'examples'], ['Nav/Board Setup', 'boardSetup'], ['Nav/Serial Monitor', 'serial'], ['Nav/Settings', 'settings'], ['Open project', 'blocks']];
  for (const f of Object.values(P)) {
    if (f === P.homeNew || f === P.boardMenu || f === P.settingsDlg) continue;
    for (const [n, k] of navMap) if (P[k] !== f) await go(f, n, P[k], { t: 'DISSOLVE', d: 0.15 });
  }
  // 1 · open a project
  await go(P.home, 'Project Blink LED', P.blocks, { t: 'DISSOLVE', d: 0.2 });
  await go(P.home, 'Open Blink LED', P.blocks, { t: 'DISSOLVE', d: 0.2 });
  await go(P.home, 'New project', P.homeNew, { t: 'DISSOLVE', d: 0.15, within: P.home.findOne(n => n.name === 'Hero') });
  await go(P.homeNew, 'Create project', P.blocks, { t: 'DISSOLVE', d: 0.2 });
  for (const n of ['Cancel', 'Close']) await go(P.homeNew, n, P.home, { t: 'DISSOLVE', d: 0.15 });
  await go(P.projects, 'Project Blink LED', P.blocks, { t: 'DISSOLVE', d: 0.2 });
  await go(P.projects, 'Project Obstacle avoider', P.code, { t: 'DISSOLVE', d: 0.2 });
  // 2 · Blocks ↔ Code
  for (const [a, b] of [['blocks', 'code'], ['blocksCollapsed', 'codeCollapsed'], ['boardMenu', 'code']]) await go(P[a], 'Segment Code', P[b]);
  for (const [a, b] of [['code', 'blocks'], ['codeCollapsed', 'blocksCollapsed']]) await go(P[a], 'Segment Blocks', P[b]);
  // 3 · board selector
  for (const k of ['blocks', 'code', 'blocksCollapsed', 'codeCollapsed']) await go(P[k], 'Board selector', P.boardMenu, { t: 'DISSOLVE', d: 0.12 });
  if (P.boardMenu) {
    const menu = P.boardMenu.findOne(n => n.name === 'Board menu');
    if (menu) {
      const dz = await hotspot(P.boardMenu, 0, 0, SW, SH, P.blocks, 'Dismiss menu', { t: 'DISSOLVE', d: 0.12 });
      P.boardMenu.insertChild(P.boardMenu.children.indexOf(menu), dz);
      for (const b of BOARDS) await go(P.boardMenu, 'Board ' + b[0], P.blocks, { t: 'DISSOLVE', d: 0.12 });
      await go(P.boardMenu, 'Board setup', P.boardSetup, { t: 'DISSOLVE', d: 0.15, within: menu });
    }
  }
  // 4 · console collapse / expand
  await go(P.blocks, 'Collapse panel', P.blocksCollapsed);
  await go(P.blocksCollapsed, 'Expand panel', P.blocks);
  await go(P.code, 'Collapse panel', P.codeCollapsed);
  await go(P.codeCollapsed, 'Expand panel', P.code);
  // 5 · examples
  await go(P.examples, 'Example Blink an LED', P.blocks, { t: 'DISSOLVE', d: 0.2 });
  if (P.home) {
    const rp = P.home.findOne(n => n.name === 'Section header Recent projects');
    const tp = P.home.findOne(n => n.name === 'Section header Start from a template');
    if (rp) await go(P.home, 'Link', P.projects, { t: 'DISSOLVE', d: 0.15, within: rp });
    if (tp) await go(P.home, 'Link', P.examples, { t: 'DISSOLVE', d: 0.15, within: tp });
  }
  // 6 · project settings
  for (const k of ['blocks', 'code', 'blocksCollapsed', 'codeCollapsed']) await go(P[k], 'Project switcher', P.settingsDlg, { t: 'DISSOLVE', d: 0.15 });
  for (const n of ['Cancel', 'Save', 'Close']) await go(P.settingsDlg, n, P.blocks, { t: 'DISSOLVE', d: 0.15 });
  const flows = [['1 · Open a project', P.home], ['2 · Switch Blocks ↔ Code', P.code], ['3 · Board selector', P.blocks], ['4 · Serial monitor expand / collapse', P.blocksCollapsed], ['5 · Navigate to Examples', P.projects], ['6 · Project settings', P.codeCollapsed]].filter(x => x[1]);
  page.flowStartingPoints = flows.map(([name, f]) => ({ nodeId: f.id, name }));
  const lg = box({ name: 'Prototype guide', dir: 'V', gap: 8, pad: 32, w: 1440, radius: 12, fill: 'color/bg/brand', parent: page });
  lg.x = 0; lg.y = -360;
  txt('Prototype', { style: 'Heading/H1', parent: lg, name: 'Title' });
  for (const l of ['1 · Open a project — Home → “Blink LED” or New project → Create project.', '2 · Switch Blocks ↔ Code — the mode switch.', '3 · Board selector — the board chip in the top bar; click outside to close.', '4 · Serial monitor — chevron on the bottom panel.', '5 · Examples — sidebar → Examples → “Blink an LED”.', '6 · Project settings — the project name in the top bar.']) txt(l, { style: 'Body/Default', parent: lg, name: 'Step', fill: true });
  return P;
}
// ============================================================================
// Orchestration: guard → pages → tokens → components → foundations → screens
// → prototype → (optional) PNG export to a local review server
// ============================================================================

async function preparePages() {
  const managed = Object.values(PAGE_NAMES);
  for (const p of figma.root.children) await p.loadAsync();
  const foreign = figma.root.children.filter(p => managed.indexOf(p.name) < 0 && p.children.length > 0);
  if (foreign.length) throw new Error('This file already has other content (page "' + foreign[0].name + '"). Run the builder in a new, empty design file.');
  // never wipe generated pages by accident: that needs the explicit Rebuild command
  const built = figma.root.children.filter(p => managed.indexOf(p.name) >= 0 && p.children.length > 0);
  if (built.length && figma.command !== 'rebuild') throw new Error('This file already has the generated pages. Use Plugins → Development → RoboCore IDE Design Builder → Rebuild to regenerate them (manual edits on those pages are replaced; version history keeps the old version).');
  const pages = {};
  // rename an empty default page to Foundations
  const empties = figma.root.children.filter(p => managed.indexOf(p.name) < 0 && p.children.length === 0);
  for (const [key, name] of Object.entries(PAGE_NAMES)) {
    let p = figma.root.children.find(x => x.name === name);
    if (!p && empties.length) { p = empties.shift(); p.name = name; }
    if (!p) { p = figma.createPage(); p.name = name; }
    pages[key] = p;
  }
  // order pages 01..05
  Object.values(PAGE_NAMES).forEach((name, i) => { const p = figma.root.children.find(x => x.name === name); if (p) figma.root.insertChild(i, p); });
  // remove leftover empty pages
  for (const p of figma.root.children.slice()) if (managed.indexOf(p.name) < 0 && p.children.length === 0 && figma.root.children.length > 5) p.remove();
  // clear managed pages (re-run safety: everything here is generated)
  for (const p of Object.values(pages)) for (const c of p.children.slice()) c.remove();
  return pages;
}

function waitForUI(type, ms) {
  return new Promise((resolve) => {
    const t = setTimeout(() => { figma.ui.off('message', h); resolve(null); }, ms);
    const h = (msg) => { if (msg && msg.type === type) { clearTimeout(t); figma.ui.off('message', h); resolve(msg); } };
    figma.ui.on('message', h);
  });
}
let UI_OPEN = false;
async function openReview() {
  if (!UI_OPEN) { figma.showUI(__html__, { visible: false, width: 240, height: 80 }); UI_OPEN = true; }
  for (let i = 0; i < 4; i++) {
    figma.ui.postMessage({ type: 'ping' });
    const pong = await waitForUI('pong', 3000);
    if (pong && pong.ok) return true;
  }
  return false;
}
async function exportForReview(items) {
  let n = 0;
  for (const [name, node, scale] of items) {
    if (!node || node.removed) continue;
    try {
      const bytes = await node.exportAsync({ format: 'PNG', constraint: { type: 'SCALE', value: scale } });
      figma.ui.postMessage({ type: 'png', name, bytes });
      await waitForUI('ack', 20000);
      n++;
    } catch (e) { warn('export ' + name + ': ' + e.message); }
  }
  REPORT.exported = (REPORT.exported || 0) + n;
}
async function sendReport() {
  try {
    figma.ui.postMessage({ type: 'report', report: REPORT });
    await waitForUI('ack', 8000);
  } catch (e) { /* UI not open */ }
}

async function main() {
  const T = Date.now();
  const mark = (k) => { REPORT.timings[k] = Date.now() - T; };
  const pages = await preparePages();
  mark('pages');
  await setupFonts();
  await setupTokens();
  mark('tokens');

  await figma.setCurrentPageAsync(pages.components);
  await buildComponentsPage(pages.components);
  await applyLinks();
  mark('components');

  await figma.setCurrentPageAsync(pages.foundations);
  buildFoundations(pages.foundations);
  await applyLinks();
  mark('foundations');

  await figma.setCurrentPageAsync(pages.ide);
  const IDE = buildIdePage(pages.ide);
  await applyLinks();
  mark('ide');
  await yieldUI();

  await figma.setCurrentPageAsync(pages.screens);
  const SCR = buildScreensPage(pages.screens);
  await applyLinks();
  mark('screens');
  await yieldUI();

  await figma.setCurrentPageAsync(pages.prototype);
  await buildPrototype(pages.prototype, IDE, SCR);
  mark('prototype');

  // page canvas backgrounds
  for (const p of Object.values(pages)) p.backgrounds = [{ type: 'SOLID', color: hexToRgb('#E9E2D2') }];

  REPORT.counts.ideFrames = Object.keys(IDE).length;
  REPORT.counts.screenFrames = Object.keys(SCR).length;

  // optional: export PNGs for review (only if the local review server answers)
  const review = await openReview();
  REPORT.export = review ? 'on' : 'skipped (no local review server)';
  if (review) {
    await figma.setCurrentPageAsync(pages.ide);
    const items = [];
    for (const [k, f] of Object.entries(IDE)) items.push(['ide_' + k + '.png', f, 1]);
    for (const [k, f] of Object.entries(SCR)) items.push(['screen_' + k + '.png', f, 1]);
    await exportForReview(items);
    await figma.setCurrentPageAsync(pages.components);
    const comps = pages.components.children[0];
    if (comps) await exportForReview(comps.children.map(fam => ['comp_' + fam.name.replace(/[^\w]+/g, '_') + '.png', fam, 0.6]));
    await figma.setCurrentPageAsync(pages.foundations);
    const fnd = pages.foundations.children[0];
    if (fnd) await exportForReview(fnd.children.map(sec => ['found_' + sec.name.replace(/[^\w]+/g, '_') + '.png', sec, 0.6]));
    await figma.setCurrentPageAsync(pages.prototype);
    await exportForReview(pages.prototype.children.filter(c => c.type === 'FRAME').slice(0, 3).map(c => ['proto_' + c.name.replace(/[^\w]+/g, '_') + '.png', c, 0.5]));
  }
  REPORT.timings.total = Date.now() - T;
  await sendReport();
  await figma.setCurrentPageAsync(pages.foundations);
  figma.viewport.scrollAndZoomIntoView(pages.foundations.children);
}

main().then(() => {
  const msg = 'RoboCore IDE design built — ' + (REPORT.errors.length ? REPORT.errors.length + ' error(s), ' : '') + (REPORT.counts.icons || 0) + ' icons, ' + (REPORT.counts.blocks || 0) + ' blocks, ' + ((REPORT.counts.ideFrames || 0) + (REPORT.counts.screenFrames || 0)) + ' screens';
  figma.closePlugin(msg);
}).catch(async (e) => {
  REPORT.errors.push('FATAL: ' + e.message + ' | ' + (e.stack || '').split('\n').slice(0, 6).join(' | '));
  try { if (await openReview()) await sendReport(); } catch (x) { /* ignore */ }
  figma.closePlugin('RoboCore IDE builder stopped: ' + e.message);
});
